/**
 * Nigeria's administrative divisions: 37 states (36 + FCT) and all 774 local
 * government areas, with centroids.
 *
 * This replaces `country-state-city` for Nigerian locations. That package
 * carries only 424 "cities" for the whole country — 8 for Lagos, 3 for Kano —
 * so most towns a driver could live in were simply unlistable. LGAs are the
 * official administrative unit, so the set is complete, stable, and bounded.
 *
 * `id` is the stable key to persist and match on; `name` is display text that
 * may be respelled. Generated file — edit the generator, not the data.
 *
 * Source: https://github.com/open-admin-data/nigeria-administrative-divisions
 *   data/all-state.json + data/all-lga.json (CC-BY-4.0, "Open Admin Data")
 */

export type NigeriaLga = {
  id: string;
  name: string;
  lat: number;
  lon: number;
};

export type NigeriaState = {
  id: string;
  name: string;
  lat: number;
  lon: number;
  lgas: NigeriaLga[];
};

