/**
 * Legacy state spellings that must keep resolving. Existing profiles were saved
 * with `country-state-city` names, and the backend city seeds use "FCT" — the
 * Federal Capital Territory is the only state all three spell differently.
 */
const STATE_NAME_ALIASES: Record<string, string> = {
  "abuja federal capital territory": "NG015",
  "federal capital territory": "NG015",
  "fct": "NG015",
  "fct, abuja": "NG015",
  "abuja": "NG015",
};

const normalize = (value?: string | null) =>
  String(value ?? "").trim().toLowerCase();

const STATES_BY_NAME: Record<string, NigeriaState> = {};
const STATES_BY_ID: Record<string, NigeriaState> = {};
for (const state of NIGERIA_STATES) {
  STATES_BY_NAME[normalize(state.name)] = state;
  STATES_BY_ID[state.id] = state;
}

/** Resolve a stored state name (current or legacy spelling) to its record. */
export function findNigeriaState(name?: string | null): NigeriaState | undefined {
  const key = normalize(name);
  if (!key) return undefined;
  const aliased = STATE_NAME_ALIASES[key];
  return aliased ? STATES_BY_ID[aliased] : STATES_BY_NAME[key];
}

/** Resolve a stored LGA name within a state. Falls back to a country-wide match. */
export function findNigeriaLga(
  stateName?: string | null,
  lgaName?: string | null
): NigeriaLga | undefined {
  const key = normalize(lgaName);
  if (!key) return undefined;
  const state = findNigeriaState(stateName);
  const pool = state ? state.lgas : NIGERIA_STATES.flatMap((s) => s.lgas);
  return pool.find((lga) => normalize(lga.name) === key);
}
